import{decodeSimulator078,applySimulatorDelta078}from'./simulator-codec-078.js';
import{fetchCohortJSON}from'./current-cohort-loader.js';
import{careerFamilies}from'./guide-state.js';
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),degree=p=>p.routes.some(x=>['college','graduate'].includes(x.key)),money=n=>Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n):'Unassessed';
const anchor=document.getElementById('evidence-benchmark');
if(anchor){const host=document.createElement('details'),url=new URL(location.href);host.id='simulator-repair-078';host.open=url.searchParams.get('study')==='simulator078'||location.hash==='#simulator-repair-078';host.innerHTML='<summary><strong>Previous research · blinded review and structured simulator repair</strong></summary><p>Loading the complete paired 2,000-profile replay…</p>';anchor.before(host);
async function loadRepair(){if(host.dataset.loaded)return;host.dataset.loaded='true';
try{const d=decodeSimulator078(await fetchCohortJSON('./simulator-repair-078.json.gz')),catalog=d.catalog,offer=(r,k)=>{const[id,score,budget,supported,missing,contrary]=r.pool[k];return{...catalog[id],r:score,budget:d.budgets[budget],supported,missing,contrary};},list=(r,arm,category)=>r[arm][category].map(k=>offer(r,k)),get=(id)=>host.querySelector('#'+id);let page=0,filtered=[],profiles=null;
 host.innerHTML=`<summary><strong>Previous research · blinded review and simulator repair · 0.78</strong></summary><p><strong>Live flow unchanged.</strong> Both cohorts use the same current matcher, frozen profiles, question exposure, earnings and education definitions. This study changes only scoped structured simulator answers.</p><div class="benchmark-controls"><label>Cohort<select id="repair-cohort"><option value="all">All original models · 1,000</option><option value="development">Original development · 758</option><option value="holdout">Original holdout · 30</option><option value="holdout049">Earlier fresh holdout · 12</option><option value="holdout056">Expansion holdout · 200</option><option value="grok075">Grok-authored cohort · 1,000</option></select></label><label>Education<select id="repair-education"><option value="all">Every education level</option><option value="degree">Bachelor + graduate</option><option value="college">Bachelor</option><option value="graduate">Graduate / professional</option><option value="program">Associate / specialist</option><option value="work">Learn at work</option><option value="apprenticeship">Apprenticeship</option></select></label><label>Cases<select id="repair-cases"><option value="changed">Changed Top sets</option><option value="all">Every model</option><option value="no-top">No repaired supported Top</option><option value="no-degree">No repaired degree Top</option><option value="withdrawn">Withdrawn supported claims</option><option value="unknown">Remaining unknown bound questions</option><option value="broad-conflict">Top with broad-interest disagreement</option><option value="review-concern">Blinded-review answer concern</option><option value="unreviewed">Unreviewed repaired combination</option></select></label><label>Find profile<input id="repair-query" type="search" placeholder="Name or ID"></label></div><div id="repair-overview"></div><details><summary>What the blinded review found · 192 profiles / 384 items</summary><div id="repair-review"></div><p>Fresh Grok AI sessions saw shuffled A/B answers and profile evidence, without executor labels or career outcomes. This is the same provider as one executor, not human validation. Two items per selected changed-result profile: these are diagnostic judgments, not population accuracy rates. Both, neither and unresolved are retained.</p></details><p id="repair-status" role="status"></p><div class="table-scroll"><table><thead><tr><th>Frozen model</th><th>Existing simulator · current matcher</th><th>Scoped simulator repair · same matcher</th><th>Exact evidence, unknowns and review</th></tr></thead><tbody id="repair-body"></tbody></table></div><div class="pagination"><button id="repair-prev">Previous</button><span id="repair-page"></span><button id="repair-next">Next</button><button id="repair-csv">Download this view · CSV</button></div><details><summary>Scope correction and retained first pass</summary><p>After the first replay, two bindings were found to add an unnecessary generic precision prerequisite. Those were corrected globally while preserving unknown interests and explicit conflicts. Preliminary holdout totals had been seen, so this is further calibration.</p><p>Original Top ${d.firstPass.summary.all.afterTop} → ${d.summary.all.afterTop}; degree ${d.firstPass.summary.all.afterDegree} → ${d.summary.all.afterDegree}. Grok-cohort Top ${d.firstPass.summary.grok075.afterTop} → ${d.summary.grok075.afterTop}; degree ${d.firstPass.summary.grok075.afterDegree} → ${d.summary.grok075.afterDegree}.</p><button id="repair-first-pass">Download complete verified first-pass JSON</button><p id="repair-first-pass-status" role="status"></p></details><details><summary>Protocol, scope and remaining limits</summary>${d.limits.map(s=>'<p>'+h(s)+'</p>').join('')}<p>New answers differing from both A and B were not themselves reviewed blindly. Narrative-answer concerns are visible in review notes; the 172 narrative profiles are preserved rather than reinterpreted by word matching.</p></details><p><a href="./simulator-repair-078.json.gz">Complete replay, all education levels, earnings, rules and blinded judgments · gzip JSON</a></p>`;
 get('repair-cohort').value=url.searchParams.get('repairCohort')||'all';get('repair-query').value=url.searchParams.get('repairQuery')||'';get('repair-education').value=url.searchParams.get('repairEducation')||'all';get('repair-cases').value=url.searchParams.get('repairCase')||(url.searchParams.get('repairQuery')?'all':'changed');for(const[id,fallback]of[['repair-cohort','all'],['repair-education','all'],['repair-cases','changed']])if(!get(id).value)get(id).value=fallback;
 const offerFilter=ps=>ps.filter(p=>get('repair-education').value==='all'||p.routes.some(x=>get('repair-education').value==='degree'?['college','graduate'].includes(x.key):x.key===get('repair-education').value));
 const chip=(p,label)=>`<article class="pending-offer"><strong><a href="../#/journey/profession/${h(p.id)}">${h(p.title)}</a></strong><small>${h(label)} · ${h(p.routes.map(x=>x.label).join(' / '))}</small><small>${h(p.fields.map(id=>careerFamilies.find(x=>x.id===id)?.title||id).join(' / '))} · interest correlation ${p.r?.toFixed(3)??'unmeasured'}</small>${p.supported&&p.r<0?'<small class="review-flag">Broad interest pattern differs; inspect the specific evidence before adopting this result.</small>':''}<small>${money(p.budget.amount)} / year · ${h(p.budget.reason)} · ${p.budget.covers===true?'proxy covers lifestyle':p.budget.covers===false?'proxy below lifestyle budget':'lifestyle unassessed'}</small></article>`;
 const label=(q,v)=>q.type==='specific'?({0:'Unknown / unfamiliar',1:'Yes',2:'No',3:'Unsure'}[v]):q.type==='rating'?({0:'Unknown / unfamiliar',1:'Strongly dislike',2:'Dislike',3:'Neutral / unsure',4:'Like',5:'Strongly like'}[v]):v===0?'Unknown / unfamiliar':v===-1?'Not for me':(q.options||[]).filter((x,i)=>v&2**i).map(x=>x.text).join(' · ');
 const view=(r,arm)=>{const top=list(r,arm,'top'),extra=list(r,arm,'other'),candidates=list(r,arm,'candidates');return offerFilter(top).map(p=>chip(p,'Supported Top')).join('')+(!offerFilter(top).length?'<p>No Top in this education view</p>':'')+(offerFilter(extra).length?`<details><summary>${offerFilter(extra).length} supported alternatives outside Top three</summary>${offerFilter(extra).map(p=>chip(p,'Supported alternative')).join('')}</details>`:'')+`<details><summary>${offerFilter(candidates).length} exploration candidates · unconfirmed</summary>${offerFilter(candidates).map(p=>chip(p,'Unconfirmed · '+p.missing.length+' missing checks'+(p.contrary.length?' · conflicting answer':''))).join('')||'None'}</details>`;};
 function render(){const cohort=get('repair-cohort').value,scope=d.rows.filter(r=>cohort==='all'?r.cohort!=='grok075':r.cohort===cohort),s=d.summary[cohort],q=get('repair-query').value.toLowerCase(),type=get('repair-cases').value;const bars=[['Supported Top','Top'],['Bachelor / graduate Top','Degree'],['Graduate Top','Graduate'],['Top covers lifestyle','Covers']];get('repair-overview').innerHTML=bars.map(([title,key])=>`<div class="repair-bar"><strong>${title}: ${s['before'+key]} → ${s['after'+key]} / ${s.models}</strong><div class="repair-track" title="Before"><i style="width:${100*s['before'+key]/s.models}%;background:#537266"></i></div><div class="repair-track" title="Repaired"><i style="width:${100*s['after'+key]/s.models}%;background:#326fa4"></i></div><small>${s['gained'+key]} gain / ${s['lost'+key]} lose coverage</small></div>`).join('')+`<p>${s.addedClaims} added supported career claims · ${s.withdrawnClaims} withdrawn. Questions with a repair binding still unknown: ${s.unknownBefore} → ${s.unknownAfter} / ${scope.reduce((n,r)=>n+r.auditCount,0)} bound questions. These are question counts, not models.</p><p><strong>Broad-interest disagreements need review:</strong> ${scope.filter(r=>list(r,'before','top').some(p=>p.r<0)).length} → ${scope.filter(r=>list(r,'after','top').some(p=>p.r<0)).length} profiles have a Top with negative broad-interest correlation. Specific activity evidence can still support interest; this disagreement needs interpretation before adopting the research changes.</p><p>All original holdout groups remain separate in the cohort selector. Original development: ${d.summary.development.beforeTop} → ${d.summary.development.afterTop} / 758 Top. Grok-authored 1,000: ${d.summary.grok075.beforeTop} → ${d.summary.grok075.afterTop} Top, ${d.summary.grok075.beforeDegree} → ${d.summary.grok075.afterDegree} degree Top. The two cohorts are never pooled. Question exposure differs across profiles/cohorts; each before/after pair keeps its own fixed exposure. Typical student survey completion was not simulated.</p>`;
 const rs=d.review.summary[cohort],js=d.review.judgments.filter(j=>cohort==='all'?j.cohort!=='grok075':j.cohort===cohort);get('repair-review').innerHTML=`<p>Selected cohort: ${rs.profiles} reviewed profiles / ${rs.items} items.</p>`+[['existing','Existing answer preferred'],['grok','Grok answer preferred'],['both','Both defensible'],['neither','Neither defensible'],['unresolved','Unresolved']].map(([k,t])=>`<div class="repair-bar"><span>${t}: ${rs[k]} / ${rs.items}</span><div class="repair-track"><i style="width:${100*rs[k]/Math.max(1,rs.items)}%;background:#817558"></i></div></div>`).join('')+`<p>Overreach judgments: existing ${rs.existingOverreach}; Grok ${rs.grokOverreach}. Among repaired answers matching a reviewed A/B response, ${js.filter(j=>j.answerChanged&&['overreach','contradiction'].includes(j.repairedVerdict)).length} / ${js.filter(j=>j.answerChanged&&j.repairedVerdict!=='not reviewed').length} reviewed changed items retain an overreach/contradiction concern. ${js.filter(j=>j.repairedVerdict==='not reviewed').length} repaired combinations differ from both reviewed choices and remain unreviewed. Unchanged answer concerns: ${js.filter(j=>!j.answerChanged&&['overreach','contradiction'].includes(j.repairedVerdict)).length} question items; these are not counts of bad career matches. ${d.freeze.authoringItems} development items from ${d.freeze.authoringProfiles} profiles informed repairs; later development and all evaluation judgments stayed uninspected through the rule freeze.</p>`;
 filtered=scope.filter(r=>(!q||(r.name+' '+r.id).toLowerCase().includes(q))&&(type==='all'||type==='changed'&&!r.exactTopSet||type==='no-top'&&!r.after.top.length||type==='no-degree'&&!list(r,'after','top').some(degree)||type==='withdrawn'&&r.removedSupported.length||type==='unknown'&&r.remainingUnknowns.length||type==='broad-conflict'&&list(r,'after','top').some(p=>p.r<0)||type==='review-concern'&&d.review.judgments.some(j=>j.modelId===r.id&&['overreach','contradiction'].includes(j.repairedVerdict))||type==='unreviewed'&&d.review.judgments.some(j=>j.modelId===r.id&&j.repairedVerdict==='not reviewed'))&&(get('repair-education').value==='all'||offerFilter([...list(r,'before','supported'),...list(r,'after','supported'),...list(r,'after','candidates')]).length));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/20)-1));get('repair-status').textContent=filtered.length+' models in this view. Bars use the full selected cohort before education/case filters. Offer lists follow the education filter; answer/claim-change counts describe the complete replay for each model.';
 get('repair-body').innerHTML=filtered.slice(page*20,page*20+20).map(r=>{const notes=d.review.judgments.filter(x=>x.modelId===r.id);return `<tr><th scope="row">${h(r.name)}<small>${h(r.id)} · ${h(r.cohort)} · ${h(r.profileKind)}</small><button data-repair-profile="${h(r.id)}">Inspect frozen profile</button><div id="repair-profile-${h(r.id)}"></div><button data-repair-transcript="${h(r.id)}">Inspect all ${r.questions} answers</button><div id="repair-transcript-${h(r.id)}"></div></th><td>${view(r,'before')}</td><td>${view(r,'after')}</td><td><p>${r.changedAnswers} changed answers · ${r.addedSupported.length} added / ${r.removedSupported.length} withdrawn supported claims.</p><details><summary>Career additions and withdrawals</summary><p>Added support: ${h(offerFilter(r.addedSupported.map(id=>catalog[id]).filter(Boolean)).map(p=>p.title).join(' · ')||'None')}</p><p>Withdrawn support: ${h(offerFilter(r.removedSupported.map(id=>catalog[id]).filter(Boolean)).map(p=>p.title).join(' · ')||'None')}</p><p>Added Top: ${h(offerFilter(r.addedTop.map(id=>catalog[id]).filter(Boolean)).map(p=>p.title).join(' · ')||'None')}<br/>Removed Top: ${h(offerFilter(r.removedTop.map(id=>catalog[id]).filter(Boolean)).map(p=>p.title).join(' · ')||'None')}</p></details><details><summary>Inspect exact changed answers</summary>${r.questionChanges.map(a=>{const q=d.questionDictionary[a.questionId];return `<p><strong>${h(q.prompt)}</strong><br/>Before: ${h(label(q,a.before))}<br/>Repaired: ${h(label(q,a.after))}</p><pre>${h(JSON.stringify(a.audit,null,2))}</pre>`;}).join('')||'No answers changed.'}</details><details><summary>${r.remainingUnknowns.length} bound questions remain unknown</summary>${r.remainingUnknowns.map(a=>'<p><strong>'+h(d.questionDictionary[a.questionId].prompt)+'</strong><br/>'+h(d.rules.questions[a.questionId]?.reason||'Each option keeps its own required activity facts; absent preferences remain unknown.')+'</p><pre>'+h(JSON.stringify(a.missing||a.options,null,2))+'</pre>').join('')||'None'}</details>${notes.length?`<details><summary>Executor-blinded review · ${notes.length} items</summary>${notes.map(x=>`<p><strong>${h(x.prompt)}</strong><br/>Existing: ${h(x.existingVerdict)} · Grok: ${h(x.grokVerdict)} · preferred: ${h(x.preferredExecutor)}<br/>Repaired answer: ${h(x.repairedVerdict)}${x.answerChanged?' · changed':' · unchanged'}<br/>${h(x.reason)}</p><pre>${h(JSON.stringify(x.evidence,null,2))}</pre>`).join('')}</details>`:''}</td></tr>`;}).join('')||'<tr><td colspan="4">No models meet these filters.</td></tr>';
 get('repair-page').textContent=`Page ${page+1} of ${Math.max(1,Math.ceil(filtered.length/20))}`;get('repair-prev').disabled=page===0;get('repair-next').disabled=(page+1)*20>=filtered.length;
 for(const button of host.querySelectorAll('[data-repair-transcript]'))button.onclick=async()=>{button.disabled=true;try{profiles??=await fetchCohortJSON('./executor-profiles-077.json.gz');const m=profiles.models.find(m=>m.id===button.dataset.repairTranscript),r=d.rows.find(r=>r.id===m.id),changes=new Map(r.questionChanges.map(q=>[q.scope+':'+q.questionId,q.after]));get('repair-transcript-'+m.id).innerHTML='<details open><summary>Complete frozen question exposure · before and repaired answers</summary>'+m.questions.map((k,i)=>{const q=profiles.definitions[k],before=m.baseline[i],after=changes.get(q.scope+':'+q.id)??before;return '<p><strong>'+h(q.prompt)+'</strong><br/>Before: '+h(label(q,before))+'<br/>Repaired: '+h(label(q,after))+'</p>';}).join('')+'</details>';button.textContent='Complete transcript loaded';}catch(e){button.disabled=false;button.textContent='Retry complete transcript';}};
 for(const button of host.querySelectorAll('[data-repair-profile]'))button.onclick=async()=>{button.disabled=true;try{profiles??=await fetchCohortJSON('./executor-profiles-077.json.gz');get('repair-profile-'+button.dataset.repairProfile).innerHTML='<pre>'+h(JSON.stringify(profiles.models.find(m=>m.id===button.dataset.repairProfile).profile,null,2))+'</pre>';}catch(e){button.disabled=false;button.textContent='Retry profile';}};
 }
 for(const id of['repair-cohort','repair-education','repair-cases','repair-query'])get(id).addEventListener(id==='repair-query'?'input':'change',()=>{page=0;const u=new URL(location.href);u.searchParams.set('study','simulator078');u.searchParams.set('repairCohort',get('repair-cohort').value);u.searchParams.set('repairEducation',get('repair-education').value);u.searchParams.set('repairCase',get('repair-cases').value);u.searchParams.set('repairQuery',get('repair-query').value);u.hash='simulator-repair-078';history.replaceState(null,'',u);render();});get('repair-prev').onclick=()=>{page--;render();};get('repair-next').onclick=()=>{page++;render();};get('repair-first-pass').onclick=async()=>{const button=get('repair-first-pass');button.disabled=true;try{get('repair-first-pass-status').textContent='Restoring and verifying the complete first pass…';const delta=decodeSimulator078(await fetchCohortJSON('./simulator-repair-078-first-pass.json.gz')),sha=async x=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(x)))).map(x=>x.toString(16).padStart(2,'0')).join('');if(await sha(JSON.stringify(d))!==delta.baseJSONSHA256)throw Error('Archive base differs; reload the page.');const raw=JSON.stringify(applySimulatorDelta078(d,delta.operations));if(await sha(raw)!==delta.originalJSONSHA256)throw Error('Archive checksum failed.');const url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='fieldguide-simulator-078-first-pass.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);get('repair-first-pass-status').textContent='Complete first pass verified and downloaded.';}catch(e){get('repair-first-pass-status').textContent=e.message;}finally{button.disabled=false;}};get('repair-csv').onclick=()=>{const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"',csv=[['id','name','cohort','before_top','after_top','added_claims','withdrawn_claims','unknown_bound_questions'],...filtered.map(r=>[r.id,r.name,r.cohort,offerFilter(list(r,'before','top')).map(p=>p.title).join(' | '),offerFilter(list(r,'after','top')).map(p=>p.title).join(' | '),r.addedSupported.length,r.removedSupported.length,r.remainingUnknowns.length])].map(r=>r.map(cell).join(',')).join('\n'),u=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=u;a.download='fieldguide-simulator-repair-078.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};render();
}catch(e){host.innerHTML='<summary>Simulator repair study</summary><p>Unable to load the complete study: '+h(e.message)+'</p>';host.dataset.loaded='';}}
host.addEventListener('toggle',()=>{if(host.open)loadRepair();});if(host.open)loadRepair();}
